2.2 Reading the data
The accommodation series is read exactly as in Project 1.


Code
raw &lt;- read_excel(tourism_file)

nights_sold &lt;- raw |&gt;
  filter(H03 == "B64100") |&gt;
  select(starts_with("MO")) |&gt;
  pivot_longer(everything(), names_to = "code", values_to = "nights") |&gt;
  mutate(Month  = yearmonth(make_date(as.integer(substr(code, 5, 8)),
                                      as.integer(substr(code, 3, 4)), 1L)),
         nights = as.numeric(nights)) |&gt;
  filter(!is.na(nights)) |&gt;
  select(Month, nights) |&gt;
  as_tsibble(index = Month) |&gt;
  filter_index("2015 Jan" ~ .) |&gt;
  mutate(period = case_when(
    Month &lt;  covid_start ~ "Pre-COVID",
    Month &lt;= covid_end   ~ "COVID window",
    TRUE                 ~ "Post-COVID"
  ))

stopifnot(!has_gaps(nights_sold)$.gaps)   # no missing months in the index




Code
nights_sold |&gt;
  ggplot(aes(as.Date(Month), nights)) +
  annotate("rect", xmin = as.Date(covid_start), xmax = as.Date(covid_end),
           ymin = -Inf, ymax = Inf, alpha = 0.15, fill = "firebrick") +
  geom_line(colour = "steelblue4") +
  scale_y_continuous(labels = scales::label_comma()) +
  labs(x = NULL, y = "Nights sold (thousands)")








Figure 1: Monthly stay unit nights sold (thousands), January 2015 to June 2026, with the COVID window shaded.





The full exploratory analysis of the accommodation series is in Project 1 and is not repeated here. The points that matter for this project are: the seasonal shape is very stable from year to year, so seasonality can be represented by fixed monthly effects; a log transformation stabilises the size of the seasonal swings; the April 2020 collapse was followed by a recovery that took about two years; and the post-COVID level is still below the pre-COVID level (Figure 1).

3.3 STL decomposition


Code
nights_sold |&gt;
  model(STL(log(nights) ~ trend(window = 13) + season(window = "periodic"),
            robust = TRUE)) |&gt;
  components() |&gt;
  autoplot() +
  labs(x = NULL)








Figure 4: Robust STL decomposition of log nights sold, January 2015 to June 2026, with a fixed (periodic) seasonal component.





The log scale is used because the seasonal swings are roughly proportional to the level (they shrank when the level fell in 2020 and 2021), so a log transformation turns multiplicative seasonality into additive seasonality. The Guerrero method, applied to the pre-COVID data, gives a Box–Cox parameter of \(\hat\lambda\) = -0.90. This is below 0 (the log), close to an inverse transformation, so the Guerrero method suggests an even stronger transformation than the log. I do not follow this estimate, for three reasons. First, the Guerrero method chooses \(\lambda\) by relating the spread of the series to its level across subseries, and before COVID the level barely moves (Table 1: all pre-COVID months lie between about 1,900 and 2,600 thousand), so there is little information about how the variance changes with the level and \(\hat\lambda\) is poorly determined. Second, the clearest evidence on that relationship comes from 2020 and 2021, when the seasonal swings shrank roughly in proportion to the level, which is the behaviour the log describes. Third, the log is easy to interpret (differences of logs are approximately percentage changes) and is used in Projects 3 and 4, which keeps the projects comparable. The transformation is therefore a judgement call, and comparing the log with a Box–Cox transformation at \(\hat\lambda\) is noted as a limitation. On the pre-COVID data the strength of seasonality is 0.93 and the strength of trend is 0.64 (both measured from 0 to 1), so seasonality is the dominant feature. In Figure 4 the COVID collapse is absorbed almost entirely by the trend and the remainder, while the seasonal component is unaffected.

4.1 The filter, likelihood, smoother and forecasts
The filter follows the structure of the notes’ KF() function (predict the state, predict \(y\), update, with \(K_t = 0\) for a missing month), written for a state vector instead of a scalar.


Code
# Kalman filter (course notes, KF()), for a state vector ---------------------
# mod = list(FF, GG, V, W, m0, C0); y may contain NA (missing months).
# a1, R1: optional first predictive distribution (used for the SARIMA check).
KF &lt;- function(y, mod, a1 = NULL, R1 = NULL) {
  FF &lt;- mod$FF; GG &lt;- mod$GG; V &lt;- mod$V; W &lt;- mod$W
  N &lt;- length(y); p &lt;- ncol(FF); I_p &lt;- diag(p)
  at &lt;- mt &lt;- Kt &lt;- matrix(0, N, p); Rt &lt;- Ct &lt;- array(0, c(p, p, N))
  ft &lt;- Qt &lt;- et &lt;- rep(NA_real_, N)
  m &lt;- mod$m0; C &lt;- mod$C0
  for (i in 1:N) {
    ## predict theta
    if (i == 1 && !is.null(a1)) { a &lt;- a1; R &lt;- R1 } else {
      a &lt;- as.numeric(GG %*% m)
      R &lt;- GG %*% C %*% t(GG) + W
    }
    ## predict y
    f &lt;- sum(FF * a)
    Q &lt;- as.numeric(FF %*% R %*% t(FF)) + V
    ## posterior: a missing month carries no information, so K = 0
    if (is.na(y[i])) {
      m &lt;- a; C &lt;- R
    } else {
      K &lt;- R %*% t(FF) / Q
      e &lt;- y[i] - f
      m &lt;- a + as.numeric(K) * e
      IKF &lt;- I_p - K %*% FF
      C &lt;- IKF %*% R %*% t(IKF) + V * K %*% t(K)     # Joseph form of R - K F R
      C &lt;- (C + t(C)) / 2
      et[i] &lt;- e; Kt[i, ] &lt;- K
    }
    at[i, ] &lt;- a; Rt[, , i] &lt;- R; ft[i] &lt;- f; Qt[i] &lt;- Q
    mt[i, ] &lt;- m; Ct[, , i] &lt;- C
  }
  list(at = at, Rt = Rt, ft = ft, Qt = Qt, et = et, Kt = Kt, mt = mt, Ct = Ct,
       m0 = mod$m0, C0 = mod$C0, N = N)
}

# Log likelihood: sum of log N(e_t; 0, Q_t) over observed months, dropping the
# first d because of the diffuse prior
KF_loglik &lt;- function(kf, d) {
  ok &lt;- which(!is.na(kf$et))
  if (d &gt; 0) ok &lt;- ok[-seq_len(d)]
  -0.5 * sum(log(2 * pi) + log(kf$Qt[ok]) + kf$et[ok]^2 / kf$Qt[ok])
}

# Standardised forecast errors e_t / sqrt(Q_t), after the diffuse period
std_resid &lt;- function(kf, d) {
  r  &lt;- kf$et / sqrt(kf$Qt)
  ok &lt;- which(!is.na(r))
  r[ok[seq_len(d)]] &lt;- NA
  r
}

# Kalman smoother (course notes): s_t = m_t + J_t (s_{t+1} - a_{t+1}) ---------
KS &lt;- function(kf, mod) {
  GG &lt;- mod$GG; N &lt;- kf$N; p &lt;- ncol(kf$mt)
  st &lt;- matrix(0, N, p); St &lt;- Jt &lt;- array(0, c(p, p, N))
  st[N, ] &lt;- kf$mt[N, ]; St[, , N] &lt;- kf$Ct[, , N]
  for (t in (N - 1):1) {
    J &lt;- kf$Ct[, , t] %*% t(GG) %*% solve(kf$Rt[, , t + 1])
    st[t, ] &lt;- kf$mt[t, ] + J %*% (st[t + 1, ] - kf$at[t + 1, ])
    St[, , t] &lt;- kf$Ct[, , t] - J %*% (kf$Rt[, , t + 1] - St[, , t + 1]) %*% t(J)
    Jt[, , t] &lt;- J
  }
  J0 &lt;- kf$C0 %*% t(GG) %*% solve(kf$Rt[, , 1])                 # back to theta_0
  s0 &lt;- as.numeric(kf$m0 + J0 %*% (st[1, ] - kf$at[1, ]))
  S0 &lt;- kf$C0 - J0 %*% (kf$Rt[, , 1] - St[, , 1]) %*% t(J0)
  list(st = st, St = St, Jt = Jt, s0 = s0, S0 = S0, J0 = J0)
}

# Covariance matrix of the smoothed signal F theta_t over consecutive months idx
# Cov(theta_s, theta_t | y) = J_s J_{s+1} ... J_{t-1} S_t for s &lt; t
smooth_signal_cov &lt;- function(ks, FF, idx) {
  k &lt;- length(idx); Sig &lt;- matrix(0, k, k)
  for (b in seq_len(k)) {
    Cst &lt;- ks$St[, , idx[b]]
    Sig[b, b] &lt;- FF %*% Cst %*% t(FF)
    if (b &gt; 1) for (a in (b - 1):1) {
      Cst &lt;- ks$Jt[, , idx[a]] %*% Cst
      Sig[a, b] &lt;- Sig[b, a] &lt;- FF %*% Cst %*% t(FF)
    }
  }
  Sig
}

# The same for the filter's predictions from the last observed month before idx
# Cov(theta_s, theta_t | y_{1:s-1}) = R_s (G')^(t - s) when no data arrive in between
filter_signal_cov &lt;- function(kf, mod, idx) {
  k &lt;- length(idx); Sig &lt;- matrix(0, k, k)
  for (a in seq_len(k)) {
    M &lt;- kf$Rt[, , idx[a]]
    for (b in a:k) {
      if (b &gt; a) M &lt;- M %*% t(mod$GG)
      Sig[a, b] &lt;- Sig[b, a] &lt;- mod$FF %*% M %*% t(mod$FF)
    }
  }
  Sig
}

# Smoothed state shocks w_hat_t = s_t - G s_{t-1}, standardised (auxiliary residuals)
aux_resid &lt;- function(ks, mod) {
  GG &lt;- mod$GG; N &lt;- nrow(ks$st); w &lt;- diag(mod$W); j &lt;- which(w &gt; 0)
  s_prev &lt;- rbind(ks$s0, ks$st[-N, , drop = FALSE])
  w_hat  &lt;- ks$st - s_prev %*% t(GG)
  aux &lt;- matrix(NA_real_, N, length(j))
  for (t in 1:N) {
    S_prev &lt;- if (t == 1) ks$S0 else ks$St[, , t - 1]
    J_prev &lt;- if (t == 1) ks$J0 else ks$Jt[, , t - 1]
    C_lag  &lt;- ks$St[, , t] %*% t(J_prev)                       # Cov(theta_t, theta_{t-1} | y)
    V_w    &lt;- ks$St[, , t] + GG %*% S_prev %*% t(GG) - C_lag %*% t(GG) - GG %*% t(C_lag)
    aux[t, ] &lt;- w_hat[t, j] / sqrt(pmax(w[j] - diag(V_w)[j], 1e-14))
  }
  list(w_hat = w_hat[, j, drop = FALSE], aux = aux, state = j)
}

# h-step forecasts: run the filter with h missing values attached (as in the notes)
KF_forecast &lt;- function(y, mod, h) {
  kf  &lt;- KF(c(y, rep(NA, h)), mod)
  idx &lt;- length(y) + 1:h
  tibble(h = 1:h, mean = kf$ft[idx], var = kf$Qt[idx])
}


These functions know nothing about tourism: each candidate model is a function that turns a parameter vector into the model matrices \((F, G, V, W, m_0, C_0)\).
